from pathlib import Path
from html import escape as e
import json, zipfile

OUT=Path('design/AI-LifeLab'); OUT.mkdir(parents=True,exist_ok=True)
BG='#F6F7F4'; INK='#24332E'; MUT='#64716B'; LINE='#D9E0DA'; ACC='#28765B'; TINT='#E7F0E9'
def rect(x,y,w,h,fill=BG,r=10): return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="{r}" fill="{fill}" stroke="{LINE}"/>'
def text(x,y,s,size=18,fill=INK,weight=400): return f'<text x="{x}" y="{y}" font-family="Segoe UI, Arial, sans-serif" font-size="{size}" fill="{fill}" font-weight="{weight}">{e(s)}</text>'
def button(x,y,s,w=210): return rect(x,y,w,46,ACC,8)+text(x+16,y+29,s,16,'#F6F7F4',600)
def panel(x,y,w,h,title,lines,cta=None):
    out=rect(x,y,w,h,'#FCFDF9')+text(x+24,y+37,title,23,weight=600)
    for i,s in enumerate(lines): out+=text(x+24,y+77+i*34,s,17,MUT)
    if cta: out+=button(x+24,y+h-65,cta,min(w-48,260))
    return out

