manifest=[]
for code,role,title,sub,panels in screens:
    s=f'<svg xmlns="http://www.w3.org/2000/svg" width="1440" height="1000" viewBox="0 0 1440 1000"><title>{e(code+" "+title)}</title>'
    s+=rect(0,0,1440,1000,BG,0)+rect(0,0,1440,80,'#FCFDF9',0)+text(32,49,'AI LifeLab',27,ACC,700)
    nav=['Trang chủ','Khám phá','Hướng dẫn'] if role=='Home' else (['Trang cá nhân','Thư viện','Trải nghiệm của mình'] if role=='Student' else ['Tổng quan','Lớp & nhiệm vụ','Thư viện hoạt động'])
    for i,n in enumerate(nav): s+=text(270+i*245,48,n,17)
    s+=text(1220,48,'Đăng nhập' if role=='Home' else ('Minh Anh · 8A' if role=='Student' else 'Cô Lan'),16)
    s+=text(48,126,f'{role.upper()} / {code}',13,MUT,600)+text(48,181,title,34,weight=650)+text(48,219,sub,18,MUT)
    if code=='S08':
        s+=panel(32,255,285,650,'Nhiệm vụ',['Tối ưu kết cấu cầu','Giữ trong ngân sách.','──────────────','Dữ liệu & tài nguyên','Vật liệu: thanh, nút nối','Ngân sách còn: 40/100','Tải mục tiêu: 100 đơn vị','──────────────','01 Thiết kế  [Hiện tại]','02 Thử tải','03 Quan sát','04 Phản tư'])
        s+=rect(337,255,725,530,'#ECF0EA')+text(362,291,'MÔ HÌNH TƯƠNG TÁC 2D',15,MUT,600)
        for x in range(400,1000,100): s+=f'<path d="M{x} 560 L{x+50} 440 L{x+100} 560 M{x} 560 L{x+100} 560 M{x+50} 440 L{x+150} 440" fill="none" stroke="{ACC}" stroke-width="5"/>'
        s+=text(370,670,'Chọn thanh vật liệu, sau đó chọn hai điểm nối.',19)+text(370,711,'Hoàn tác   ·   Làm lại   ·   Đặt lại bản thiết kế',16,MUT)
        s+=button(357,805,'Thử tải',180)+text(558,834,'Chuột / Cử chỉ / Quét bản vẽ',17)+text(357,895,'Tự động lưu · Bạn có thể quay lại phiên này.',16,MUT)
        s+=panel(1082,255,326,650,'AI Coach',['Bạn muốn kiểm tra','phần nào trước?','','Gợi ý chỉ xuất hiện khi','bạn yêu cầu hoặc cần hỗ trợ.','','[Nhập câu hỏi...]'],'Xin một gợi ý')
    else:
        s+=panel(48,265,850,260,panels[0][0],panels[0][1],panels[0][2])
        s+=panel(48,553,850,300,panels[1][0],panels[1][1],panels[1][2])
        s+=panel(930,265,462,588,panels[2][0],panels[2][1],panels[2][2])
    s+=text(48,965,'AI LifeLab · Khung UX desktop 1440 × 1000 · Nội dung và dữ liệu minh họa',13,MUT)+'</svg>'
    name=f'{code}.svg'; (OUT/name).write_text(s,encoding='utf-8')
    manifest.append({'id':code,'page':role,'title':title,'file':name})

(OUT/'manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2),encoding='utf-8')
html='''<!doctype html><html lang="vi"><meta charset="utf-8"><title>AI LifeLab · UX Frames</title><style>body{font-family:Segoe UI,sans-serif;margin:40px;background:#f6f7f4;color:#24332e}nav{display:flex;gap:12px;flex-wrap:wrap}a{color:#28765b}section{margin:50px 0}img{width:100%;border:1px solid #d9e0da}p{max-width:85ch;line-height:1.6}</style><h1>AI LifeLab · Khung UI/UX MVP</h1><p>23 frame desktop cho Home, Student và Teacher. SVG chứa chữ và hình vector có thể nhập vào Figma; chưa có Auto Layout, component hoặc liên kết prototype. Dữ liệu minh họa. Đây là khung bố cục, chưa phải giao diện hoàn thiện.</p><nav>'''
html+=''.join(f'<a href="#{m["id"]}">{m["id"]} {e(m["title"])}</a>' for m in manifest)+'</nav>'
html+=''.join(f'<section id="{m["id"]}"><h2>{m["id"]} · {e(m["title"])}</h2><img src="{m["file"]}" alt="{e(m["title"])}"></section>' for m in manifest)
(OUT/'index.html').write_text(html,encoding='utf-8')
print(f'Generated {len(manifest)} SVG frames in {OUT.resolve()}')
